srcDoc.css:
* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; min-height: 100vh; font-family: 'Poppins', 'Helvetica Neue', Arial, sans-serif; background: #F9F9F9; }

.pc { width: 100%; box-sizing: border-box; padding: 26px; }

.pc__header { margin-bottom: 18px; }
.pc__title { font-size: 17px; font-weight: 700; color: #1D2751; }
.pc__subtitle { margin-top: 2px; font-size: 12px; color: #4A5568; }

.pc__layout { display: grid; grid-template-columns: 220px 1fr; gap: 20px; align-items: start; width: 100%; }

@media (max-width: 720px) {
  .pc__layout { grid-template-columns: 1fr; }
  .pc__sidebar { position: static; }
  .pc__grid { grid-template-columns: 1fr; }
}

.pc__sidebar {
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 16px;
  padding: 18px;
  position: sticky;
  top: 0;
}

.pc__brand { display: flex; align-items: center; gap: 10px; margin-bottom: 18px; padding-bottom: 16px; border-bottom: 1px solid #F1F3F7; }
.pc__brand-logo { width: 40px; height: auto; flex-shrink: 0; object-fit: contain; }
.pc__brand-text { font-size: 12.5px; font-weight: 600; line-height: 1.25; color: #14327D; }

.pc__progreso-label { font-size: 10.5px; font-weight: 700; letter-spacing: 0.4px; text-transform: uppercase; color: #9CA3AF; }
.pc__progreso-track { margin-top: 8px; height: 8px; background: #F1F3F7; border-radius: 999px; overflow: hidden; }
.pc__progreso-fill { height: 100%; width: 0%; background: linear-gradient(90deg, #1E5FA8 0%, #2E7BD6 100%); border-radius: 999px; transition: width 0.4s ease-out; }
.pc__progreso-pct { margin-top: 6px; font-size: 20px; font-weight: 800; color: #14327D; }

.pc__pasos { margin-top: 20px; display: flex; flex-direction: column; gap: 4px; }

.pc__paso {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 10px;
  border-radius: 9px;
  border: none;
  background: none;
  cursor: pointer;
  text-align: left;
  font-size: 12.5px;
  font-weight: 500;
  color: #4A5568;
}
.pc__paso:hover { background: #F1F5F9; }
.pc__paso.activo { background: rgba(30,95,168,.1); color: #14327D; font-weight: 700; }
.pc__paso.no-alcanzado { opacity: 0.45; cursor: not-allowed; }

.pc__paso-numero {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 999px;
  background: #E5E7EB;
  color: #6B7280;
  font-size: 10.5px;
  font-weight: 700;
  flex-shrink: 0;
}
.pc__paso.activo .pc__paso-numero { background: #1E5FA8; color: #fff; }
.pc__paso.completo .pc__paso-numero { background: #F4880A; color: #fff; }

.pc__contenido {
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 16px;
  padding: 26px;
  min-height: 400px;
}

.pc__seccion-titulo { font-size: 15px; font-weight: 700; color: #14327D; margin-bottom: 4px; }
.pc__seccion-hint { font-size: 12px; color: #4A5568; margin-bottom: 18px; }

.pc__grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px 20px; }

.pc__campo { display: flex; flex-direction: column; gap: 5px; }
.pc__campo--full { grid-column: 1 / -1; }

.pc__label { font-size: 11.5px; font-weight: 600; color: #374151; }
.pc__label .req { color: #D6202A; margin-left: 2px; }

.pc__input, .pc__select {
  padding: 9px 12px;
  border: 1px solid #D1D5DB;
  border-radius: 8px;
  font-size: 13px;
  font-family: inherit;
  color: #1F2937;
  background: #fff;
}
.pc__input:focus, .pc__select:focus { outline: none; border-color: #1E5FA8; box-shadow: 0 0 0 2px rgba(30,95,168,.15); }
.pc__input.error, .pc__select.error { border-color: #D6202A; }

.pc__error-banner {
  background: #FCECEC;
  border: 1px solid #F2C9C9;
  border-radius: 10px;
  padding: 12px 16px;
  margin-bottom: 16px;
  font-size: 12px;
  color: #A61620;
}
.pc__error-banner ul { margin: 6px 0 0; padding-left: 18px; }

.pc__nav { display: flex; align-items: center; justify-content: space-between; margin-top: 24px; padding-top: 18px; border-top: 1px solid #F1F3F7; }
.pc__nav-izquierda { display: flex; gap: 10px; }
.pc__nav-derecha { display: flex; gap: 10px; margin-left: auto; }

.pc__toast {
  position: fixed;
  bottom: 24px;
  right: 24px;
  padding: 12px 20px;
  border-radius: 10px;
  background: #14327D;
  color: #fff;
  font-size: 12.5px;
  font-weight: 600;
  box-shadow: 0 8px 24px rgba(0,0,0,.18);
  z-index: 1000;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity 0.25s ease, transform 0.25s ease;
  pointer-events: none;
}
.pc__toast.visible { opacity: 1; transform: translateY(0); }

.pc__btn {
  padding: 9px 20px;
  border-radius: 999px;
  font-size: 12.5px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  border: none;
}
.pc__btn--primary { background: linear-gradient(90deg, #1E5FA8 0%, #2E7BD6 100%); color: #fff; }
.pc__btn--ghost { background: #fff; border: 1.5px solid #6FA3DC; color: #14327D; }
.pc__btn:disabled { opacity: 0.4; cursor: not-allowed; }

.pc__subtitulo { margin: 22px 0 12px; font-size: 13px; font-weight: 700; color: #1F2937; }
.pc__subtitulo:first-child { margin-top: 0; }

.pc__hint { margin: 0 0 14px; font-size: 12px; color: #4A5568; }
.pc__hint--warn { color: #A61620; }

.pc__checklist { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px 20px; }
.pc__checkbox { display: flex; align-items: center; gap: 8px; font-size: 12.5px; color: #374151; cursor: pointer; }
.pc__checkbox--strong { font-weight: 700; font-size: 13px; }
.pc__checkbox input[type="checkbox"] { width: 17px; height: 17px; accent-color: #1E5FA8; cursor: pointer; }

.pc__warn {
  margin: 14px 0;
  padding: 10px 14px;
  background: #FFF3CC;
  border: 1px solid #FFE08A;
  border-radius: 10px;
  color: #8A6D00;
  font-size: 12px;
}

.pc__tabla { display: flex; flex-direction: column; gap: 14px; margin-bottom: 18px; }
.pc__tabla-fila { padding: 14px; border: 1px solid #E5E7EB; border-radius: 12px; background: #FAFBFC; }
.pc__tabla-quitar {
  margin-top: 10px;
  padding: 6px 14px;
  border: 1px solid #F2C9C9;
  border-radius: 999px;
  background: #fff;
  color: #A61620;
  font-size: 11px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
}
.pc__tabla-agregar {
  align-self: flex-start;
  padding: 8px 16px;
  border: 1.5px dashed #6FA3DC;
  border-radius: 999px;
  background: #fff;
  color: #14327D;
  font-size: 12px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
}

.pc__resumen { display: flex; flex-direction: column; gap: 8px; margin-bottom: 18px; }
.pc__resumen-item { font-size: 12.5px; color: #374151; }
.pc__resumen-item strong { color: #1F2937; min-width: 140px; display: inline-block; }

.pc__status { padding: 12px 16px; border-radius: 10px; font-size: 12.5px; font-weight: 600; }
.pc__status.ok { background: #E7F7ED; color: #16A34A; border: 1px solid #B7EBC6; }
.pc__status.warn { background: #FFF3CC; color: #8A6D00; border: 1px solid #FFE08A; }

.pc__exito { display: flex; flex-direction: column; align-items: center; text-align: center; padding: 50px 20px; gap: 10px; }
.pc__exito-icono {
  width: 64px; height: 64px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 50%;
  background: #E7F7ED;
  color: #16A34A;
  font-size: 32px;
  font-weight: 700;
}
.pc__exito-titulo { font-size: 17px; font-weight: 700; color: #14327D; }
.pc__exito-caso {
  padding: 8px 20px;
  border-radius: 999px;
  background: linear-gradient(90deg, #1E5FA8 0%, #2E7BD6 100%);
  color: #fff;
  font-size: 13px;
  font-weight: 700;
}
.pc__exito-detalle { max-width: 420px; font-size: 12.5px; color: #4A5568; }

srcDoc.js:
/**
 * Wizard completo de "Perfil del Cliente" (MB-FOR-23-013) — 8 secciones:
 * Categoría, Información Personal, Dirección, Perfil Financiero (opcional),
 * Referencias (opcional), Fiscal/FATCA (opcional), PEP, Revisión. Portado de
 * perfilClienteSchema.ts + SecCategoria..SecRevision.svelte del dashboard
 * Svelte/React de referencia. Catálogos vienen del BDM real
 * (com.mercantil.parametrica.*) vía queries GetCategoriaCliente/GetPaisesParametrica/
 * GetEstadoCivil/GetTipoParentesco/GetOrigenFondos, con fallback a listas locales
 * si el BDM falla o viene vacío — mismo patrón que loadPerfilClienteCatalogos().
 */

// ── Fallbacks locales (mismos que perfilClienteCatalogos.ts) ──
const FALLBACK_CATEGORIAS = [
  { value: "TITULAR", label: "Titular" },
  { value: "CO_TITULAR", label: "Co-Titular" },
  { value: "FIRMANTE", label: "Firmante" },
  { value: "CO_DEUDOR", label: "Co-Deudor" },
  { value: "FIADOR", label: "Fiador" },
  { value: "GARANTE", label: "Garante" },
];
const FALLBACK_PAISES = ["Panamá", "Colombia", "Estados Unidos", "México", "Costa Rica", "Venezuela", "España", "Argentina", "Chile", "Perú", "Ecuador", "Brasil", "Canadá", "Otro"]
  .map((p) => ({ value: p, label: p }));
const FALLBACK_ESTADO_CIVIL = [
  { value: "SOLTERO", label: "Soltero/a" },
  { value: "CASADO", label: "Casado/a" },
  { value: "DIVORCIADO", label: "Divorciado/a" },
  { value: "VIUDO", label: "Viudo/a" },
  { value: "UNION_LIBRE", label: "Unión Libre" },
];
const FALLBACK_TIPO_PARENTESCO = [
  { value: "CONYUGE", label: "Cónyuge" },
  { value: "PADRE", label: "Padre" },
  { value: "MADRE", label: "Madre" },
  { value: "HIJO", label: "Hijo/a" },
  { value: "HERMANO", label: "Hermano/a" },
  { value: "AMIGO", label: "Amigo/a" },
  { value: "OTRO", label: "Otro" },
];
const FALLBACK_ORIGEN_FONDOS = [
  { value: "SALARIO", label: "Salario" },
  { value: "AHORRO_PERSONAL", label: "Ahorro Personal" },
  { value: "VENTA_BIENES", label: "Venta de bienes inmuebles" },
  { value: "HERENCIA", label: "Herencia" },
  { value: "ARRENDAMIENTO", label: "Arrendamiento de bienes" },
  { value: "DIVIDENDOS", label: "Dividendos" },
  { value: "PENSIONES", label: "Pensiones" },
  { value: "OTRO", label: "Otro" },
];
const SEXO = [
  { value: "F", label: "Femenino" },
  { value: "M", label: "Masculino" },
];

const MAX_RESIDENCIAS_FISCALES = 3;

function crearFormVacio() {
  return {
    categoriaCliente: "",
    informacionPersonal: {
      primerNombre: "", segundoNombre: "", primerApellido: "", segundoApellido: "",
      cedula: "", paisEmisorDocumento: "", fechaVencimientoCedula: "", pasaporte: "",
      nacionalidad: "", sexo: "", fechaNacimiento: "", paisNacimiento: "",
      estadoCivil: "", nivelEducativo: "", profesionOcupacion: "", dependientes: 0,
      correoElectronico: "", celular: "", telefonoResidencial: "",
      redSocial1: "", usuarioRedSocial1: "", redSocial2: "", usuarioRedSocial2: "",
      redSocial3: "", usuarioRedSocial3: "",
    },
    datosResidencia: {
      pais: "", estadoProvincia: "", municipioCorregimiento: "", ciudad: "",
      urbanizacion: "", calleAvenida: "", casaEdificio: "",
    },
    perfilFinanciero: {
      nombreEmpresa: "", fechaIngresoEmpresa: "", tipoNegocioRamaActividad: "", cargo: "",
      telefonoEmpresa: "", direccionFisicaEmpresa: "", origenFondos: "",
      ingresoMensual: 0, otrosIngresos: 0, origenOtrosIngresos: "",
      activosActual: 0, activosHaceDosAnos: 0, pasivosActual: 0, pasivosHaceDosAnos: 0,
    },
    referenciasBancarias: [],
    referenciasPersonales: [],
    residenciasFiscales: [],
    perfilFATCA: {
      tieneCiudadaniaEEUU: false, nacioEnEEUU: false, poseeGreenCard: false,
      reuneCondicionPresenciaSustancial: false, esResidenteFiscalEEUU: false,
      motivoResidenciaFiscal: "", esPersonaEstadounidense: false, adjuntoFormaW9: false,
    },
    datoPEP: {
      esPEPORelacionado: false, nombreApellidoPEPRelacionado: "", numeroIdentificacionPEP: "",
      parentescoPEP: "", nombreInstitucionEnte: "", pais: "", cargoPublico: "",
      periodoCargoPublico: "",
    },
  };
}

// ── Guardado parcial (localStorage), mismo patrón que perfilClienteForm.ts ──
// A diferencia de la referencia (que solo limpia el localStorage al enviar
// con éxito y deja el resto indefinidamente), aquí se agrega una expiración
// de 7 días: si el usuario guardó progreso y no volvió a completar el
// formulario en ese plazo, se descarta automáticamente al intentar
// restaurarlo — evita que datos de clientes queden guardados para siempre
// en el navegador si el wizard se abandona sin enviar.
const STORAGE_KEY = "perfilCliente:form";
const STORAGE_KEY_PASO = "perfilCliente:paso";
const EXPIRACION_MS = 7 * 24 * 60 * 60 * 1000; // 7 días

function guardarProgresoLocal() {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify({ form, guardadoEn: Date.now() }));
    window.localStorage.setItem(STORAGE_KEY_PASO, String(pasoMaximo));
    return true;
  } catch (e) {
    return false;
  }
}

function restaurarProgresoLocal() {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return false;
    const parsed = JSON.parse(raw);
    const guardadoEn = parsed && parsed.guardadoEn;
    if (!guardadoEn || Date.now() - guardadoEn > EXPIRACION_MS) {
      // Progreso vencido (>7 días) — se descarta, no se restaura.
      limpiarProgresoLocal();
      return false;
    }
    if (parsed && parsed.form) {
      form = parsed.form;
      const pasoGuardado = parseInt(window.localStorage.getItem(STORAGE_KEY_PASO) || "0", 10);
      pasoMaximo = isNaN(pasoGuardado) ? 0 : Math.min(pasoGuardado, SECCIONES.length - 1);
      pasoActivo = pasoMaximo;
      return true;
    }
    return false;
  } catch (e) {
    return false;
  }
}

function limpiarProgresoLocal() {
  try {
    window.localStorage.removeItem(STORAGE_KEY);
    window.localStorage.removeItem(STORAGE_KEY_PASO);
  } catch (e) {
    // almacenamiento no disponible; no es crítico
  }
}

function mostrarToast(mensaje) {
  const toast = document.getElementById("pc-toast");
  if (!toast) return;
  toast.textContent = mensaje;
  toast.classList.add("visible");
  setTimeout(() => toast.classList.remove("visible"), 3000);
}

let form = crearFormVacio();
let pasoActivo = 0;
let pasoMaximo = 0;
let enviando = false;
let envioExitoso = null; // { caseId } cuando ya se instanció el proceso

// ── Catálogos: se pueblan al montar vía appsmith.model (ver aplicarCatalogos) ──
let CATALOGOS = {
  categorias: FALLBACK_CATEGORIAS,
  paises: FALLBACK_PAISES,
  estadoCivil: FALLBACK_ESTADO_CIVIL,
  tipoParentesco: FALLBACK_TIPO_PARENTESCO,
  origenFondos: FALLBACK_ORIGEN_FONDOS,
};

function mapParametrica(rows, fallback, mapFn) {
  if (!Array.isArray(rows) || rows.length === 0) return fallback;
  const opts = rows
    .filter((r) => r.activo !== false)
    .map(mapFn || ((r) => ({ value: String(r.codigo || ""), label: String(r.nombre || r.codigo || "") })))
    .filter((o) => o.value !== "");
  return opts.length > 0 ? opts : fallback;
}

function req(v) {
  if (v == null) return false;
  if (typeof v === "string") return v.trim() !== "";
  if (typeof v === "number") return !isNaN(v);
  return Boolean(v);
}
function isEmail(v) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
}

const SECCIONES = [
  {
    id: "categoria",
    titulo: "Categoría del Cliente",
    hint: "Seleccione el rol del cliente: Titular, Co-Titular, Firmante, etc.",
    validate: (f) => (req(f.categoriaCliente) ? [] : ["Categoría del cliente"]),
  },
  {
    id: "informacionPersonal",
    titulo: "Información Personal",
    hint: "Datos de identificación básicos del cliente.",
    validate: (f) => {
      const e = [];
      const p = f.informacionPersonal;
      if (!req(p.primerNombre)) e.push("Primer Nombre");
      if (!req(p.primerApellido)) e.push("Primer Apellido");
      if (!req(p.cedula) || p.cedula.trim().length < 5) e.push("Cédula (mínimo 5 caracteres)");
      if (!req(p.paisEmisorDocumento)) e.push("País Emisor del documento");
      if (!req(p.nacionalidad)) e.push("Nacionalidad");
      if (!req(p.sexo)) e.push("Sexo");
      if (!req(p.fechaNacimiento)) e.push("Fecha de Nacimiento");
      if (!req(p.paisNacimiento)) e.push("País de Nacimiento");
      if (!req(p.estadoCivil)) e.push("Estado Civil");
      if (!req(p.correoElectronico)) e.push("Correo Electrónico");
      else if (!isEmail(p.correoElectronico)) e.push("Correo Electrónico (formato inválido)");
      if (!req(p.celular)) e.push("Celular");
      return e;
    },
  },
  {
    id: "datosResidencia",
    titulo: "Dirección de Residencia",
    hint: "Domicilio actual del cliente.",
    validate: (f) => (req(f.datosResidencia.pais) ? [] : ["País de residencia"]),
  },
  {
    id: "perfilFinanciero",
    titulo: "Perfil Financiero",
    hint: "Sección opcional pero recomendada para agilizar el proceso.",
    opcional: true,
    validate: () => [],
  },
  {
    id: "referencias",
    titulo: "Referencias",
    hint: "Referencias bancarias y personales (opcional).",
    opcional: true,
    validate: (f) => {
      const e = [];
      f.referenciasBancarias.forEach((r, i) => { if (!req(r.entidadEmisora)) e.push("Referencia Bancaria " + (i + 1) + ": Entidad Emisora"); });
      f.referenciasPersonales.forEach((r, i) => { if (!req(r.nombresApellidos)) e.push("Referencia Personal " + (i + 1) + ": Nombres y Apellidos"); });
      return e;
    },
  },
  {
    id: "fiscalFatca",
    titulo: "Fiscal y FATCA",
    hint: "Autocertificación fiscal y cuestionario FATCA (opcional).",
    opcional: true,
    validate: (f) => {
      const e = [];
      f.residenciasFiscales.forEach((r, i) => {
        if (!req(r.paisResidenciaFiscal)) e.push("Residencia Fiscal " + (i + 1) + ": País");
        if (!req(r.numeroIdentificacionFiscal)) e.push("Residencia Fiscal " + (i + 1) + ": Número de Identificación Fiscal");
      });
      return e;
    },
  },
  {
    id: "pep",
    titulo: "Persona Expuesta Políticamente (PEP)",
    hint: "Declaración PEP del cliente o relacionado.",
    validate: (f) => (typeof f.datoPEP.esPEPORelacionado === "boolean" ? [] : ["¿Es PEP o relacionado?"]),
  },
  {
    id: "revision",
    titulo: "Revisión Final",
    hint: "Revise la información antes de enviar el formulario.",
    validate: () => [],
  },
];

/** Mismo algoritmo que calcularProgreso() de perfilClienteSchema.ts. */
function contarCampos(valor) {
  if (Array.isArray(valor)) {
    return valor.reduce((acc, item) => {
      const r = contarCampos(item);
      return { total: acc.total + r.total, completos: acc.completos + r.completos };
    }, { total: 0, completos: 0 });
  }
  if (valor !== null && typeof valor === "object") {
    return Object.values(valor).reduce((acc, v) => {
      const r = contarCampos(v);
      return { total: acc.total + r.total, completos: acc.completos + r.completos };
    }, { total: 0, completos: 0 });
  }
  if (typeof valor === "string") return { total: 1, completos: valor.trim() !== "" ? 1 : 0 };
  if (typeof valor === "number") return { total: 1, completos: !isNaN(valor) && valor !== 0 ? 1 : 0 };
  return { total: 0, completos: 0 };
}
function calcularProgreso(f) {
  const { total, completos } = contarCampos(f);
  if (total === 0) return 0;
  return Math.round((completos / total) * 100);
}

function irAPaso(i) {
  if (i > pasoMaximo) return;
  pasoActivo = i;
  renderTodo();
}

function avanzar() {
  const errores = SECCIONES[pasoActivo].validate(form);
  if (errores.length > 0) {
    renderContenido(errores);
    return;
  }
  if (pasoActivo < SECCIONES.length - 1) {
    pasoActivo += 1;
    if (pasoActivo > pasoMaximo) pasoMaximo = pasoActivo;
  }
  renderTodo();
}

function retroceder() {
  if (pasoActivo > 0) {
    pasoActivo -= 1;
    renderTodo();
  }
}

/** Guarda el progreso actual en localStorage (con timestamp para la
 * expiración de 7 días) y muestra confirmación — igual que
 * handleGuardarProgreso() en PerfilClienteForm.svelte. */
function guardarProgreso() {
  const ok = guardarProgresoLocal();
  mostrarToast(ok ? "Tus avances se guardaron. Puedes continuar después." : "No se pudo guardar el progreso.");
}

/** Empieza de cero: descarta el formulario actual (sin guardarlo) y borra
 * cualquier progreso guardado — para cuando el analista quiere digitar un
 * cliente distinto sin esperar a que expire el guardado anterior. */
function limpiarYEmpezarDeNuevo() {
  const confirmado = window.confirm("¿Descartar el progreso actual y empezar con un cliente nuevo? Esta acción no se puede deshacer.");
  if (!confirmado) return;
  limpiarProgresoLocal();
  form = crearFormVacio();
  pasoActivo = 0;
  pasoMaximo = 0;
  envioExitoso = null;
  renderTodo();
  mostrarToast("Formulario reiniciado.");
}

async function enviarFormulario() {
  // Valida TODAS las secciones no-opcionales antes de enviar.
  const erroresGlobales = [];
  SECCIONES.forEach((s) => {
    if (!s.opcional) erroresGlobales.push(...s.validate(form));
  });
  if (erroresGlobales.length > 0) {
    renderContenido(erroresGlobales);
    return;
  }
  enviando = true;
  renderContenido([]);
  try {
    const result = await appsmith.triggerEvent("onEnviar", { form: JSON.stringify(form) });
  } catch (e) {
    enviando = false;
    renderContenido(["Error al enviar: " + (e && e.message ? e.message : String(e))]);
  }
}

function renderTodo() {
  renderHeader();
  renderProgreso();
  renderPasos();
  renderContenido([]);
}

/** Título + contador de paso, igual que .pc-form__header en
 * PerfilClienteForm.svelte ("Formulario MB-FOR-23-013 · Persona Natural —
 * Paso X de 8"). */
function renderHeader() {
  const subtitulo = document.getElementById("pc-subtitulo");
  if (subtitulo) {
    subtitulo.textContent = "MB-FOR-23-013 · Persona Natural — Paso " + (pasoActivo + 1) + " de " + SECCIONES.length;
  }
}

function renderProgreso() {
  const pct = calcularProgreso(form);
  const fill = document.getElementById("pc-progreso-fill");
  const label = document.getElementById("pc-progreso-pct");
  if (fill) fill.style.width = pct + "%";
  if (label) label.textContent = pct + "%";
}

function renderPasos() {
  const nav = document.getElementById("pc-pasos");
  if (!nav) return;
  nav.innerHTML = "";
  SECCIONES.forEach((s, i) => {
    const alcanzado = i <= pasoMaximo;
    const completo = pasoMaximo > i && s.validate(form).length === 0;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "pc__paso" + (i === pasoActivo ? " activo" : "") + (!alcanzado ? " no-alcanzado" : "") + (completo ? " completo" : "");
    btn.disabled = !alcanzado;

    const numero = document.createElement("span");
    numero.className = "pc__paso-numero";
    // Numeración desde 0, igual que FormSidebar.svelte (kyc-sidebar__num usa
    // {i} directo, no {i+1}) — un paso completo muestra ✓ en vez del número.
    numero.textContent = completo ? "✓" : String(i);
    btn.appendChild(numero);

    const label = document.createElement("span");
    label.textContent = s.titulo;
    btn.appendChild(label);

    btn.addEventListener("click", () => irAPaso(i));
    nav.appendChild(btn);
  });
}

function campoTexto(labelText, valor, onInput, required, tipo) {
  const wrap = document.createElement("div");
  wrap.className = "pc__campo";
  const label = document.createElement("label");
  label.className = "pc__label";
  label.innerHTML = labelText + (required ? '<span class="req">*</span>' : "");
  wrap.appendChild(label);
  const input = document.createElement("input");
  input.className = "pc__input";
  input.type = tipo || "text";
  input.value = valor == null ? "" : valor;
  input.addEventListener("input", (e) => onInput(tipo === "number" ? Number(e.target.value) : e.target.value));
  wrap.appendChild(input);
  return wrap;
}

function campoCheckbox(labelText, valor, onChange) {
  const wrap = document.createElement("label");
  wrap.className = "pc__checkbox";
  const input = document.createElement("input");
  input.type = "checkbox";
  input.checked = !!valor;
  input.addEventListener("change", (e) => onChange(e.target.checked));
  wrap.appendChild(input);
  const span = document.createElement("span");
  span.textContent = labelText;
  wrap.appendChild(span);
  return wrap;
}

function campoSelect(labelText, valor, opciones, onChange, required) {
  const wrap = document.createElement("div");
  wrap.className = "pc__campo";
  const label = document.createElement("label");
  label.className = "pc__label";
  label.innerHTML = labelText + (required ? '<span class="req">*</span>' : "");
  wrap.appendChild(label);
  const select = document.createElement("select");
  select.className = "pc__select";
  const optVacio = document.createElement("option");
  optVacio.value = "";
  optVacio.textContent = "Seleccione...";
  select.appendChild(optVacio);
  opciones.forEach((o) => {
    const opt = document.createElement("option");
    opt.value = o.value;
    opt.textContent = o.label;
    if (o.value === valor) opt.selected = true;
    select.appendChild(opt);
  });
  select.addEventListener("change", (e) => onChange(e.target.value));
  wrap.appendChild(select);
  return wrap;
}

function subtitulo(texto) {
  const h = document.createElement("h3");
