/** Tabla dinámica genérica (mismo patrón que DynamicTable.svelte): filas +
 * botón "+ Agregar" + botón quitar por fila. */
function tablaDinamica(rows, emptyRowFn, addLabel, renderRowFields, onChange, maxRows) {
  const wrap = document.createElement("div");
  wrap.className = "pc__tabla";

  rows.forEach((row, i) => {
    const fila = document.createElement("div");
    fila.className = "pc__tabla-fila";
    const grid = document.createElement("div");
    grid.className = "pc__grid";
    renderRowFields(row, i).forEach((el) => grid.appendChild(el));
    fila.appendChild(grid);

    const quitar = document.createElement("button");
    quitar.type = "button";
    quitar.className = "pc__tabla-quitar";
    quitar.textContent = "Quitar";
    quitar.addEventListener("click", () => {
      rows.splice(i, 1);
      onChange();
      renderContenido([]);
    });
    fila.appendChild(quitar);

    wrap.appendChild(fila);
  });

  if (!maxRows || rows.length < maxRows) {
    const addBtn = document.createElement("button");
    addBtn.type = "button";
    addBtn.className = "pc__tabla-agregar";
    addBtn.textContent = addLabel;
    addBtn.addEventListener("click", () => {
      rows.push(emptyRowFn());
      onChange();
      renderContenido([]);
    });
    wrap.appendChild(addBtn);
  } else {
    const limite = document.createElement("p");
    limite.className = "pc__hint pc__hint--warn";
    limite.textContent = "Límite de " + maxRows + " alcanzado.";
    wrap.appendChild(limite);
  }

  return wrap;
}

function renderContenido(erroresForzados) {
  const cont = document.getElementById("pc-contenido");
  if (!cont) return;
  cont.innerHTML = "";

  if (envioExitoso) {
    renderExito(cont);
    return;
  }

  const seccion = SECCIONES[pasoActivo];

  if (erroresForzados && erroresForzados.length > 0) {
    const banner = document.createElement("div");
    banner.className = "pc__error-banner";
    banner.innerHTML = "Faltan campos por completar:<ul>" + erroresForzados.map((e) => "<li>" + e + "</li>").join("") + "</ul>";
    cont.appendChild(banner);
  }

  const titulo = document.createElement("div");
  titulo.className = "pc__seccion-titulo";
  titulo.textContent = seccion.titulo;
  cont.appendChild(titulo);

  const hint = document.createElement("div");
  hint.className = "pc__seccion-hint";
  hint.textContent = seccion.hint;
  cont.appendChild(hint);

  if (seccion.id === "categoria") renderCategoria(cont);
  if (seccion.id === "informacionPersonal") renderInformacionPersonal(cont);
  if (seccion.id === "datosResidencia") renderDireccion(cont);
  if (seccion.id === "perfilFinanciero") renderPerfilFinanciero(cont);
  if (seccion.id === "referencias") renderReferencias(cont);
  if (seccion.id === "fiscalFatca") renderFiscalFatca(cont);
  if (seccion.id === "pep") renderPep(cont);
  if (seccion.id === "revision") renderRevision(cont);

  const nav = document.createElement("div");
  nav.className = "pc__nav";

  // Grupo izquierdo: Limpiar (empezar de cero) + Guardar progreso — mismo
  // patrón que Cancelar/Guardar progreso en PerfilClienteForm.svelte.
  const navIzquierda = document.createElement("div");
  navIzquierda.className = "pc__nav-izquierda";

  const btnLimpiar = document.createElement("button");
  btnLimpiar.type = "button";
  btnLimpiar.className = "pc__btn pc__btn--ghost";
  btnLimpiar.textContent = "Limpiar";
  btnLimpiar.title = "Descartar el progreso actual y empezar con un cliente nuevo";
  btnLimpiar.disabled = enviando;
  btnLimpiar.addEventListener("click", limpiarYEmpezarDeNuevo);
  navIzquierda.appendChild(btnLimpiar);

  const btnGuardar = document.createElement("button");
  btnGuardar.type = "button";
  btnGuardar.className = "pc__btn pc__btn--ghost";
  btnGuardar.textContent = "Guardar progreso";
  btnGuardar.disabled = enviando;
  btnGuardar.addEventListener("click", guardarProgreso);
  navIzquierda.appendChild(btnGuardar);

  nav.appendChild(navIzquierda);

  // Grupo derecho: Atrás + Siguiente/Enviar.
  const navDerecha = document.createElement("div");
  navDerecha.className = "pc__nav-derecha";

  const btnAtras = document.createElement("button");
  btnAtras.type = "button";
  btnAtras.className = "pc__btn pc__btn--ghost";
  btnAtras.textContent = "Atrás";
  btnAtras.disabled = pasoActivo === 0 || enviando;
  btnAtras.addEventListener("click", retroceder);
  navDerecha.appendChild(btnAtras);

  const btnSiguiente = document.createElement("button");
  btnSiguiente.type = "button";
  btnSiguiente.className = "pc__btn pc__btn--primary";
  const esUltimo = pasoActivo === SECCIONES.length - 1;
  btnSiguiente.textContent = esUltimo ? (enviando ? "Enviando..." : "Enviar Formulario") : "Siguiente";
  btnSiguiente.disabled = enviando;
  btnSiguiente.addEventListener("click", esUltimo ? enviarFormulario : avanzar);
  navDerecha.appendChild(btnSiguiente);

  nav.appendChild(navDerecha);

  cont.appendChild(nav);
}

