    grid2.appendChild(campoTexto("Período del Cargo", pep.periodoCargoPublico, (v) => { pep.periodoCargoPublico = v; }, false));
  }
}

function renderRevision(cont) {
  const p = form.informacionPersonal;
  const nombreCompleto = [p.primerNombre, p.segundoNombre, p.primerApellido, p.segundoApellido].filter(Boolean).join(" ");

  const resumen = document.createElement("div");
  resumen.className = "pc__resumen";
  cont.appendChild(resumen);

  const items = [
    ["Categoría", form.categoriaCliente || "—"],
    ["Nombre Completo", nombreCompleto || "—"],
    ["Cédula", p.cedula || "—"],
    ["Correo", p.correoElectronico || "—"],
    ["Celular", p.celular || "—"],
  ];
  items.forEach(([label, value]) => {
    const item = document.createElement("div");
    item.className = "pc__resumen-item";
    item.innerHTML = "<strong>" + label + ":</strong> <span>" + value + "</span>";
    resumen.appendChild(item);
  });

  const erroresObligatorios = [];
  SECCIONES.forEach((s) => { if (!s.opcional) erroresObligatorios.push(...s.validate(form)); });
  const valido = erroresObligatorios.length === 0;

  const status = document.createElement("div");
  status.className = "pc__status " + (valido ? "ok" : "warn");
  status.textContent = valido ? "✓ Formulario completo y válido" : "⚠ Hay campos obligatorios sin completar";
  cont.appendChild(status);
}

function renderExito(cont) {
  const caja = document.createElement("div");
  caja.className = "pc__exito";
  caja.innerHTML =
    '<div class="pc__exito-icono">✓</div>' +
    '<div class="pc__exito-titulo">¡Perfil del Cliente creado con éxito!</div>' +
    '<div class="pc__exito-caso">Caso #' + envioExitoso.caseId + '</div>' +
    '<div class="pc__exito-detalle">El proceso de creación de cuenta ha sido iniciado. El siguiente paso es la Solicitud de Producto.</div>';
  cont.appendChild(caja);
}

/** Aplica los catálogos recibidos vía appsmith.model — ya vienen mapeados
 * (o con fallback ya resuelto) desde el binding defaultModel del propio
 * widget en el JSON, porque un CUSTOM_WIDGET corre en un iframe aislado:
 * NO tiene acceso a las variables globales de las queries (GetCategoriaCliente,
 * etc.), solo al objeto appsmith. Referenciar una query directo en este JS
 * lanza ReferenceError y detiene todo el script silenciosamente — por eso
 * antes no se pintaba nada. */
function aplicarCatalogos(model) {
  CATALOGOS = {
    categorias: (model && model.categorias) || FALLBACK_CATEGORIAS,
    paises: (model && model.paises) || FALLBACK_PAISES,
    estadoCivil: (model && model.estadoCivil) || FALLBACK_ESTADO_CIVIL,
    tipoParentesco: (model && model.tipoParentesco) || FALLBACK_TIPO_PARENTESCO,
    origenFondos: (model && model.origenFondos) || FALLBACK_ORIGEN_FONDOS,
  };
}

let yaMontado = false;

appsmith.onReady(() => {
  aplicarCatalogos(appsmith.model);

  if (!yaMontado) {
    yaMontado = true;
    // Restaura el progreso guardado (si existe y no venció el plazo de 7
    // días) SOLO la primera vez que este widget se monta — evitar volver a
    // restaurar en cada onModelChange, que pisaría cambios del usuario en
    // curso.
    restaurarProgresoLocal();
    // Dispara la carga real de catálogos (las queries corren desde el
    // binding onMontar, cableado en el JSON del widget) — no se ejecutan
    // solas al cargar la app entera, solo al entrar a este tab.
    appsmith.triggerEvent("onMontar", {});
  }

  renderTodo();

  if (typeof appsmith.onModelChange === "function") {
    appsmith.onModelChange((m) => {
      aplicarCatalogos(m);
      renderPasos();
      if (m && m.envioResultado && !envioExitoso) {
        envioExitoso = m.envioResultado;
        enviando = false;
        // Caso instanciado con éxito: recién AHORA se limpia el progreso
        // guardado — si el envío hubiera fallado (rama de abajo), el
        // localStorage se conserva para que el analista pueda reintentar sin
        // volver a digitar todo.
        limpiarProgresoLocal();
        renderContenido([]);
      }
      if (m && m.envioError && enviando) {
        enviando = false;
        renderContenido([m.envioError]);
      }
    });
  }
});

