/**
 * Wizard completo de "Perfil del Cliente" (MB-FOR-23-013) — 8 secciones:
 * Categoría, Información Personal, Dirección, Perfil Financiero (opcional),
 * Referencias (opcional), Fiscal/FATCA (opcional), PEP, Revisión. Portado de
 * perfilClienteSchema.ts + SecCategoria..SecRevision.svelte del dashboard
 * Svelte/React de referencia. Catálogos vienen del BDM real
 * (com.mercantil.parametrica.*) vía queries GetCategoriaCliente/GetPaisesParametrica/
 * GetEstadoCivil/GetTipoParentesco/GetOrigenFondos, con fallback a listas locales
 * si el BDM falla o viene vacío — mismo patrón que loadPerfilClienteCatalogos().
 */

// ── Fallbacks locales (mismos que perfilClienteCatalogos.ts) ──
const FALLBACK_CATEGORIAS = [
  { value: "TITULAR", label: "Titular" },
  { value: "CO_TITULAR", label: "Co-Titular" },
  { value: "FIRMANTE", label: "Firmante" },
  { value: "CO_DEUDOR", label: "Co-Deudor" },
  { value: "FIADOR", label: "Fiador" },
  { value: "GARANTE", label: "Garante" },
];
const FALLBACK_PAISES = ["Panamá", "Colombia", "Estados Unidos", "México", "Costa Rica", "Venezuela", "España", "Argentina", "Chile", "Perú", "Ecuador", "Brasil", "Canadá", "Otro"]
  .map((p) => ({ value: p, label: p }));
const FALLBACK_ESTADO_CIVIL = [
  { value: "SOLTERO", label: "Soltero/a" },
  { value: "CASADO", label: "Casado/a" },
  { value: "DIVORCIADO", label: "Divorciado/a" },
  { value: "VIUDO", label: "Viudo/a" },
  { value: "UNION_LIBRE", label: "Unión Libre" },
];
const FALLBACK_TIPO_PARENTESCO = [
  { value: "CONYUGE", label: "Cónyuge" },
  { value: "PADRE", label: "Padre" },
  { value: "MADRE", label: "Madre" },
  { value: "HIJO", label: "Hijo/a" },
  { value: "HERMANO", label: "Hermano/a" },
  { value: "AMIGO", label: "Amigo/a" },
  { value: "OTRO", label: "Otro" },
];
const FALLBACK_ORIGEN_FONDOS = [
  { value: "SALARIO", label: "Salario" },
  { value: "AHORRO_PERSONAL", label: "Ahorro Personal" },
  { value: "VENTA_BIENES", label: "Venta de bienes inmuebles" },
  { value: "HERENCIA", label: "Herencia" },
  { value: "ARRENDAMIENTO", label: "Arrendamiento de bienes" },
  { value: "DIVIDENDOS", label: "Dividendos" },
  { value: "PENSIONES", label: "Pensiones" },
  { value: "OTRO", label: "Otro" },
];
const SEXO = [
  { value: "F", label: "Femenino" },
  { value: "M", label: "Masculino" },
];

const MAX_RESIDENCIAS_FISCALES = 3;

function crearFormVacio() {
  return {
    categoriaCliente: "",
    informacionPersonal: {
      primerNombre: "", segundoNombre: "", primerApellido: "", segundoApellido: "",
      cedula: "", paisEmisorDocumento: "", fechaVencimientoCedula: "", pasaporte: "",
      nacionalidad: "", sexo: "", fechaNacimiento: "", paisNacimiento: "",
      estadoCivil: "", nivelEducativo: "", profesionOcupacion: "", dependientes: 0,
      correoElectronico: "", celular: "", telefonoResidencial: "",
      redSocial1: "", usuarioRedSocial1: "", redSocial2: "", usuarioRedSocial2: "",
      redSocial3: "", usuarioRedSocial3: "",
    },
    datosResidencia: {
      pais: "", estadoProvincia: "", municipioCorregimiento: "", ciudad: "",
      urbanizacion: "", calleAvenida: "", casaEdificio: "",
    },
    perfilFinanciero: {
      nombreEmpresa: "", fechaIngresoEmpresa: "", tipoNegocioRamaActividad: "", cargo: "",
      telefonoEmpresa: "", direccionFisicaEmpresa: "", origenFondos: "",
      ingresoMensual: 0, otrosIngresos: 0, origenOtrosIngresos: "",
      activosActual: 0, activosHaceDosAnos: 0, pasivosActual: 0, pasivosHaceDosAnos: 0,
    },
    referenciasBancarias: [],
    referenciasPersonales: [],
    residenciasFiscales: [],
    perfilFATCA: {
      tieneCiudadaniaEEUU: false, nacioEnEEUU: false, poseeGreenCard: false,
      reuneCondicionPresenciaSustancial: false, esResidenteFiscalEEUU: false,
      motivoResidenciaFiscal: "", esPersonaEstadounidense: false, adjuntoFormaW9: false,
    },
    datoPEP: {
      esPEPORelacionado: false, nombreApellidoPEPRelacionado: "", numeroIdentificacionPEP: "",
      parentescoPEP: "", nombreInstitucionEnte: "", pais: "", cargoPublico: "",
      periodoCargoPublico: "",
    },
  };
}

// ── Guardado parcial (localStorage), mismo patrón que perfilClienteForm.ts ──
// A diferencia de la referencia (que solo limpia el localStorage al enviar
// con éxito y deja el resto indefinidamente), aquí se agrega una expiración
// de 7 días: si el usuario guardó progreso y no volvió a completar el
// formulario en ese plazo, se descarta automáticamente al intentar
// restaurarlo — evita que datos de clientes queden guardados para siempre
// en el navegador si el wizard se abandona sin enviar.
const STORAGE_KEY = "perfilCliente:form";
const STORAGE_KEY_PASO = "perfilCliente:paso";
const EXPIRACION_MS = 7 * 24 * 60 * 60 * 1000; // 7 días

function guardarProgresoLocal() {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify({ form, guardadoEn: Date.now() }));
    window.localStorage.setItem(STORAGE_KEY_PASO, String(pasoMaximo));
    return true;
  } catch (e) {
    return false;
  }
}

function restaurarProgresoLocal() {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return false;
    const parsed = JSON.parse(raw);
    const guardadoEn = parsed && parsed.guardadoEn;
    if (!guardadoEn || Date.now() - guardadoEn > EXPIRACION_MS) {
      // Progreso vencido (>7 días) — se descarta, no se restaura.
      limpiarProgresoLocal();
      return false;
    }
    if (parsed && parsed.form) {
      form = parsed.form;
      const pasoGuardado = parseInt(window.localStorage.getItem(STORAGE_KEY_PASO) || "0", 10);
      pasoMaximo = isNaN(pasoGuardado) ? 0 : Math.min(pasoGuardado, SECCIONES.length - 1);
      pasoActivo = pasoMaximo;
      return true;
    }
    return false;
  } catch (e) {
    return false;
  }
}

function limpiarProgresoLocal() {
  try {
    window.localStorage.removeItem(STORAGE_KEY);
    window.localStorage.removeItem(STORAGE_KEY_PASO);
  } catch (e) {
    // almacenamiento no disponible; no es crítico
  }
}

function mostrarToast(mensaje) {
  const toast = document.getElementById("pc-toast");
  if (!toast) return;
  toast.textContent = mensaje;
  toast.classList.add("visible");
  setTimeout(() => toast.classList.remove("visible"), 3000);
}

let form = crearFormVacio();
let pasoActivo = 0;
let pasoMaximo = 0;
let enviando = false;
let envioExitoso = null; // { caseId } cuando ya se instanció el proceso

// ── Catálogos: se pueblan al montar vía appsmith.model (ver aplicarCatalogos) ──
let CATALOGOS = {
  categorias: FALLBACK_CATEGORIAS,
  paises: FALLBACK_PAISES,
  estadoCivil: FALLBACK_ESTADO_CIVIL,
  tipoParentesco: FALLBACK_TIPO_PARENTESCO,
  origenFondos: FALLBACK_ORIGEN_FONDOS,
};

function mapParametrica(rows, fallback, mapFn) {
  if (!Array.isArray(rows) || rows.length === 0) return fallback;
  const opts = rows
    .filter((r) => r.activo !== false)
    .map(mapFn || ((r) => ({ value: String(r.codigo || ""), label: String(r.nombre || r.codigo || "") })))
    .filter((o) => o.value !== "");
  return opts.length > 0 ? opts : fallback;
}

function req(v) {
  if (v == null) return false;
  if (typeof v === "string") return v.trim() !== "";
  if (typeof v === "number") return !isNaN(v);
  return Boolean(v);
}
function isEmail(v) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
}

const SECCIONES = [
  {
    id: "categoria",
    titulo: "Categoría del Cliente",
    hint: "Seleccione el rol del cliente: Titular, Co-Titular, Firmante, etc.",
    validate: (f) => (req(f.categoriaCliente) ? [] : ["Categoría del cliente"]),
  },
  {
    id: "informacionPersonal",
    titulo: "Información Personal",
    hint: "Datos de identificación básicos del cliente.",
    validate: (f) => {
      const e = [];
      const p = f.informacionPersonal;
      if (!req(p.primerNombre)) e.push("Primer Nombre");
      if (!req(p.primerApellido)) e.push("Primer Apellido");
      if (!req(p.cedula) || p.cedula.trim().length < 5) e.push("Cédula (mínimo 5 caracteres)");
      if (!req(p.paisEmisorDocumento)) e.push("País Emisor del documento");
      if (!req(p.nacionalidad)) e.push("Nacionalidad");
      if (!req(p.sexo)) e.push("Sexo");
