/** Mismo algoritmo que calcularProgreso() de perfilClienteSchema.ts. */
function contarCampos(valor) {
  if (Array.isArray(valor)) {
    return valor.reduce((acc, item) => {
      const r = contarCampos(item);
      return { total: acc.total + r.total, completos: acc.completos + r.completos };
    }, { total: 0, completos: 0 });
  }
  if (valor !== null && typeof valor === "object") {
    return Object.values(valor).reduce((acc, v) => {
      const r = contarCampos(v);
      return { total: acc.total + r.total, completos: acc.completos + r.completos };
    }, { total: 0, completos: 0 });
  }
  if (typeof valor === "string") return { total: 1, completos: valor.trim() !== "" ? 1 : 0 };
  if (typeof valor === "number") return { total: 1, completos: !isNaN(valor) && valor !== 0 ? 1 : 0 };
  return { total: 0, completos: 0 };
}
function calcularProgreso(f) {
  const { total, completos } = contarCampos(f);
  if (total === 0) return 0;
  return Math.round((completos / total) * 100);
}

function irAPaso(i) {
  if (i > pasoMaximo) return;
  pasoActivo = i;
  renderTodo();
}

function avanzar() {
  const errores = SECCIONES[pasoActivo].validate(form);
  if (errores.length > 0) {
    renderContenido(errores);
    return;
  }
  if (pasoActivo < SECCIONES.length - 1) {
    pasoActivo += 1;
    if (pasoActivo > pasoMaximo) pasoMaximo = pasoActivo;
  }
  renderTodo();
}

function retroceder() {
  if (pasoActivo > 0) {
    pasoActivo -= 1;
    renderTodo();
  }
}

/** Guarda el progreso actual en localStorage (con timestamp para la
 * expiración de 7 días) y muestra confirmación — igual que
 * handleGuardarProgreso() en PerfilClienteForm.svelte. */
function guardarProgreso() {
  const ok = guardarProgresoLocal();
  mostrarToast(ok ? "Tus avances se guardaron. Puedes continuar después." : "No se pudo guardar el progreso.");
}

/** Empieza de cero: descarta el formulario actual (sin guardarlo) y borra
 * cualquier progreso guardado — para cuando el analista quiere digitar un
 * cliente distinto sin esperar a que expire el guardado anterior. */
function limpiarYEmpezarDeNuevo() {
  const confirmado = window.confirm("¿Descartar el progreso actual y empezar con un cliente nuevo? Esta acción no se puede deshacer.");
  if (!confirmado) return;
  limpiarProgresoLocal();
  form = crearFormVacio();
  pasoActivo = 0;
  pasoMaximo = 0;
  envioExitoso = null;
  renderTodo();
  mostrarToast("Formulario reiniciado.");
}

async function enviarFormulario() {
  // Valida TODAS las secciones no-opcionales antes de enviar.
  const erroresGlobales = [];
  SECCIONES.forEach((s) => {
    if (!s.opcional) erroresGlobales.push(...s.validate(form));
  });
  if (erroresGlobales.length > 0) {
    renderContenido(erroresGlobales);
    return;
  }
  enviando = true;
  renderContenido([]);
  try {
    const result = await appsmith.triggerEvent("onEnviar", { form: JSON.stringify(form) });
  } catch (e) {
    enviando = false;
    renderContenido(["Error al enviar: " + (e && e.message ? e.message : String(e))]);
  }
}

function renderTodo() {
  renderHeader();
  renderProgreso();
  renderPasos();
  renderContenido([]);
}

/** Título + contador de paso, igual que .pc-form__header en
 * PerfilClienteForm.svelte ("Formulario MB-FOR-23-013 · Persona Natural —
 * Paso X de 8"). */
function renderHeader() {
  const subtitulo = document.getElementById("pc-subtitulo");
  if (subtitulo) {
    subtitulo.textContent = "MB-FOR-23-013 · Persona Natural — Paso " + (pasoActivo + 1) + " de " + SECCIONES.length;
  }
}

function renderProgreso() {
  const pct = calcularProgreso(form);
  const fill = document.getElementById("pc-progreso-fill");
  const label = document.getElementById("pc-progreso-pct");
  if (fill) fill.style.width = pct + "%";
  if (label) label.textContent = pct + "%";
}

function renderPasos() {
  const nav = document.getElementById("pc-pasos");
  if (!nav) return;
  nav.innerHTML = "";
  SECCIONES.forEach((s, i) => {
    const alcanzado = i <= pasoMaximo;
    const completo = pasoMaximo > i && s.validate(form).length === 0;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "pc__paso" + (i === pasoActivo ? " activo" : "") + (!alcanzado ? " no-alcanzado" : "") + (completo ? " completo" : "");
    btn.disabled = !alcanzado;

    const numero = document.createElement("span");
    numero.className = "pc__paso-numero";
    // Numeración desde 0, igual que FormSidebar.svelte (kyc-sidebar__num usa
    // {i} directo, no {i+1}) — un paso completo muestra ✓ en vez del número.
    numero.textContent = completo ? "✓" : String(i);
    btn.appendChild(numero);

    const label = document.createElement("span");
    label.textContent = s.titulo;
    btn.appendChild(label);

    btn.addEventListener("click", () => irAPaso(i));
    nav.appendChild(btn);
  });
}

function campoTexto(labelText, valor, onInput, required, tipo) {
  const wrap = document.createElement("div");
  wrap.className = "pc__campo";
  const label = document.createElement("label");
  label.className = "pc__label";
  label.innerHTML = labelText + (required ? '<span class="req">*</span>' : "");
  wrap.appendChild(label);
  const input = document.createElement("input");
  input.className = "pc__input";
  input.type = tipo || "text";
  input.value = valor == null ? "" : valor;
  input.addEventListener("input", (e) => onInput(tipo === "number" ? Number(e.target.value) : e.target.value));
  wrap.appendChild(input);
  return wrap;
}

function campoCheckbox(labelText, valor, onChange) {
  const wrap = document.createElement("label");
  wrap.className = "pc__checkbox";
  const input = document.createElement("input");
  input.type = "checkbox";
  input.checked = !!valor;
  input.addEventListener("change", (e) => onChange(e.target.checked));
  wrap.appendChild(input);
  const span = document.createElement("span");
  span.textContent = labelText;
  wrap.appendChild(span);
  return wrap;
}

function campoSelect(labelText, valor, opciones, onChange, required) {
  const wrap = document.createElement("div");
  wrap.className = "pc__campo";
  const label = document.createElement("label");
  label.className = "pc__label";
  label.innerHTML = labelText + (required ? '<span class="req">*</span>' : "");
  wrap.appendChild(label);
  const select = document.createElement("select");
  select.className = "pc__select";
  const optVacio = document.createElement("option");
  optVacio.value = "";
  optVacio.textContent = "Seleccione...";
  select.appendChild(optVacio);
  opciones.forEach((o) => {
    const opt = document.createElement("option");
    opt.value = o.value;
    opt.textContent = o.label;
    if (o.value === valor) opt.selected = true;
    select.appendChild(opt);
  });
  select.addEventListener("change", (e) => onChange(e.target.value));
  wrap.appendChild(select);
  return wrap;
}

function subtitulo(texto) {
